func TestDotSortsTheAgentsLargestFirst(t *testing.T) {
	m := atWideAgents(t, sortUsage(1))
	if got := visibleIDs(m); got != ",a01,a02,a03" {
		t.Fatalf("tree order = %q", got)
	}
	m, _ = opened(t, m, ".")
	if got := visibleIDs(m); got != "a01,a02,,a03" {
		t.Errorf("sorted order = %q, want a01,a02,,a03", got)
	}
