		sum += r.share
		if i > 0 && totals[r.ID] > totals[rows[i-1].ID] {
			t.Errorf("row %d (%d tokens) outranks row %d (%d)", i, totals[r.ID], i-1, totals[rows[i-1].ID])
		}
	}
	if sum != shareScale {
		t.Errorf("shares add up to %d, want %d", sum, shareScale)
